<div class="container-fluid py-4"><a class="btn btn-outline-secondary mb-3" href="<?= base_url('cliente/creditos') ?>">← Volver a créditos</a><h2>Crédito #<?= (int) $credito->id_credito ?></h2><div class="row g-3 my-1"><div class="col-md-4"><div class="card"><div class="card-body"><small>Total</small><h4>$<?= number_format($credito->monto_total,0,',','.') ?></h4></div></div></div><div class="col-md-4"><div class="card"><div class="card-body"><small>Abonado</small><h4>$<?= number_format($credito->total_abonado,0,',','.') ?></h4></div></div></div><div class="col-md-4"><div class="card"><div class="card-body"><small>Saldo pendiente</small><h4>$<?= number_format($credito->saldo_pendiente,0,',','.') ?></h4></div></div></div></div><div class="card mt-4"><div class="card-body"><h5>Cuotas</h5><div class="table-responsive"><table class="table"><thead><tr><th>#</th><th>Vencimiento</th><th>Valor</th><th>Abonado</th><th>Saldo</th></tr></thead><tbody><?php foreach ($cuotas as $cuota): ?><tr><td><?= (int) $cuota->numero_cuota ?></td><td><?= !empty($cuota->fecha_vencimiento) ? date('d/m/Y',strtotime($cuota->fecha_vencimiento)) : '—' ?></td><td>$<?= number_format($cuota->monto_cuota,0,',','.') ?></td><td>$<?= number_format($cuota->total_abonado,0,',','.') ?></td><td>$<?= number_format($cuota->saldo_cuota,0,',','.') ?></td></tr><?php endforeach ?></tbody></table></div></div></div></div>
